function BookSpineGluePotStandMaker.completeMaking(m) local q=1.0+(BookSpineGluePotStandMaker.getQualityBonus()/100); if BookSpineGluePotStandMaker.maker then q=q+(BookSpineGluePotStandMaker.maker.skill/140) end; q=math.min(2.5,q); BookSpineGluePotStandMaker.productStock[m.productType]=(BookSpineGluePotStandMaker.productStock[m.productType] or 0)+m.quantity; BookSpineGluePotStandMaker.totalProducts=BookSpineGluePotStandMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if BookSpineGluePotStandMaker.maker then BookSpineGluePotStandMaker.maker.itemsMade=BookSpineGluePotStandMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then BookSpineGluePotStandMaker.maker.skill=math.min(100,BookSpineGluePotStandMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Stojalo izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"bookspinegluepotstand.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
